<?php
require_once __DIR__.'/includes/db.php';require_once __DIR__.'/includes/functions.php';
if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$id=(int)($_POST['id']??0);$action=$_POST['action']??'';if($action==='remove'){unset($_SESSION['cart'][$id]);}elseif($action==='update'){$_SESSION['cart'][$id]=max(1,(int)($_POST['quantity']??1));}$p=$conn->prepare("SELECT stock FROM products WHERE id=?");$p->bind_param('i',$id);$p->execute();$row=$p->get_result()->fetch_assoc();if(!$row)unset($_SESSION['cart'][$id]);else $_SESSION['cart'][$id]=min($_SESSION['cart'][$id],(int)$row['stock']);set_flash('Keranjang diperbarui.');redirect('cart.php');}
$cart=$_SESSION['cart']??[];$items=[];$total=0;
if($cart){$ids=array_map('intval',array_keys($cart));$in=implode(',',$ids);$res=$conn->query("SELECT id,name,price,stock,image_url FROM products WHERE id IN ($in) AND is_active=1");while($r=$res->fetch_assoc()){$r['quantity']=$cart[$r['id']];$r['subtotal']=$r['price']*$r['quantity'];$total+=$r['subtotal'];$items[]=$r;}}
$page_title='Keranjang Belanja';require_once __DIR__.'/includes/header.php';
?>
<h1 class="section-title mb-4">Keranjang Belanja</h1>
<?php if(!$items): ?><div class="empty-state"><h4>Keranjangmu masih kosong</h4><p class="text-secondary">Yuk, temukan produk yang kamu butuhkan.</p><a class="btn btn-primary" href="<?= e(url('index.php')) ?>">Belanja Sekarang</a></div>
<?php else: ?><div class="row g-4"><div class="col-lg-8"><div class="surface-card p-3">
<?php foreach($items as $it): ?><div class="cart-row"><img src="<?= e(product_image($it['image_url'])) ?>" alt=""><div class="flex-grow-1"><strong><?= e($it['name']) ?></strong><div class="price"><?= rupiah($it['price']) ?></div><small class="text-secondary">Subtotal: <?= rupiah($it['subtotal']) ?></small></div><form method="post" class="d-flex gap-2 align-items-center"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$it['id'] ?>"><input type="hidden" name="action" value="update"><input class="form-control form-control-sm" style="width:75px" type="number" min="1" max="<?= (int)$it['stock'] ?>" name="quantity" value="<?= (int)$it['quantity'] ?>"><button class="btn btn-outline-primary btn-sm">Ubah</button></form><form method="post"><input type="hidden" name="csrf" value="<?= e(csrf_token()) ?>"><input type="hidden" name="id" value="<?= (int)$it['id'] ?>"><input type="hidden" name="action" value="remove"><button class="btn btn-outline-danger btn-sm">Hapus</button></form></div><?php endforeach; ?>
</div></div><div class="col-lg-4"><div class="surface-card p-4"><h5>Ringkasan Belanja</h5><div class="d-flex justify-content-between my-3"><span>Total</span><strong class="price"><?= rupiah($total) ?></strong></div><a class="btn btn-primary w-100" href="<?= e(url('checkout.php')) ?>">Lanjut Checkout</a></div></div></div><?php endif; ?>
<?php require_once __DIR__.'/includes/footer.php'; ?>
